"""
yambo_runlevels.py
==================
What yambo puts in its input for given runlevels, per version: the names it
writes when asked for an input (``yambo -F file <options>``), with each one's
description, unit and verbosity, from the tags ``5.1.1``, ``5.2.4``,
``5.3.0`` and ``5.4-beta`` (as 5.4).

How the data are made, for adding a version (``scripts/extract-input-names.py``):
``src/interface/INIT_activate.F`` is translated rule by rule: each
``call initactivate(mode,'names')``, ``CPU_activate``, ``X_activate`` and
``INIT_QP_ctl_switch`` under the ``if``/``else`` blocks that lead to it
becomes a rule (condition, action, argument). Fortran conditions become a
small language (``and``, ``or``, ``not``, comparisons, ``any_``, ``all_``,
``has``, ``match``, ``same``, ``runlevel``), evaluated here by a parser that
allows nothing else. ``#if defined`` blocks are those of the plain ``yambo``
executable: ``_RT``, ``_SC``, ``_NL``, ``_ELPH``, ``_PHEL``, ``_QED`` belong to
yambo_rt, yambo_sc, yambo_nl, yambo_ph and are left out; ``_MPI`` and
``_SCALAPACK`` depend on the build and stay as ``MPI`` and ``SCALAPACK``.
``INIT.F`` gives the runlevels' switches (``l_optics = runlevel_is_on('optics')``,
and those set from the kernel's and response's modes) and the runlevels a
runlevel brings (GW brings ``HF_and_locXC``; screening and optics bring
``dipoles``). ``INIT_load.F`` gives each name's description, Fortran variable,
unit and verbosity (empty: written by default; else written only with
yambo's ``-V`` for that level).

Meant for ``yambopy.io``.
"""

