class InputName(str):
    """A name yambo writes in its input, with what INIT_load.F says of it."""

    def __new__(cls, name, info=None):
        self = super().__new__(cls, name)
        info = info or {}
        self.text = info.get('text', '')
        self.unit = info.get('unit', '')            # E (energy), G (G vectors), T...
        self.verbosity = info.get('verbosity', '')  # '' basic; else yambo's -V level
        return self


def _version_key(version):
    if not YAMBO_RUNLEVELS:
        raise ValueError('no runlevel data')
    versions = sorted(YAMBO_RUNLEVELS, key=lambda v: tuple(int(x) for x in v.split('.')))
    if version is None:
        return versions[-1]
    # '5.2.4', '5.2' or (5, 2, 4)
    parts = version.split('.') if isinstance(version, str) else list(version)
    wanted = tuple(int(x) for x in parts[:2])
    older = [v for v in versions if tuple(int(x) for x in v.split('.'))[:2] <= wanted]
    return older[-1] if older else versions[0]


def input_names(runlevels, values=None, version=None, *, mpi=True, scalapack=False,
                spin_polarized=False, databases=(), new_input=False):
    """
    The names yambo writes in its input for these runlevels.

    Parameters
    ----------
    runlevels : iterable of str
        As in the input (``optics``, ``bse``, ``bss``, ``gw0``, ``ppa``,
        ``HF_and_locXC``, ``em1d``...); those they bring are added.
    values : dict
        Input values that decide what is written: ``BSSmod`` (``"d"``: the
        diagonalisation's variables, ``WRbsWF``), ``BSKmod``, ``Chimod``,
        ``DysSolver``...
    version : str
        Yambo's version (the nearest one known at or below it).
    mpi, scalapack : bool
        How yambo was built: the parallel variables (``*_CPU``, ``*_ROLEs``)
        come with MPI.
    spin_polarized : bool
        Spin-polarised SAVE (the QP controls per spin).
    databases : iterable of str
        Databases already on disk that change what is asked: ``"X_2"`` the
        static screening, ``"X_4"`` the plasmon-pole one, ``"BS_Fxc"``,
        ``"QINDX"`` the SAVE's indices (``ndb.kindx``, made by the setup run).
    new_input : bool
        As yambo writes a new input from command-line options (``yambo -F
        file -x -p p``): the runlevels a runlevel brings are not added then
        (INIT.F adds them before the options' runlevels are on), so the
        runlevels given must be those the options set. False: as yambo
        runs an input, the runlevels it brings added (a plasmon-pole GW
        also computes dipoles, and reads ``DIP_CPU``).

    Returns
    -------
    list of InputName
        Runlevels first, then flags and variables, in the order yambo
        activates them.
    """
    data = YAMBO_RUNLEVELS[_version_key(version)]
    info = data['info']
    env = {'MPI': mpi, 'SCALAPACK': scalapack, 'SPIN_POLARIZED': spin_polarized}
    for db in ('X_2', 'X_4', 'BS_Fxc', 'QINDX'):
        env[f'io_{db}_err'] = 0 if db in databases else 1
    lowered = {k.lower(): v for k, v in (values or {}).items()}
    for name, entry in info.items():
        if 'fortran' in entry and name.lower() in lowered:
            env[entry['fortran']] = lowered[name.lower()]
    levels = list(dict.fromkeys(runlevels))

    def switches():
        for condition, action, arg in data['switches']:
            if action == 'set' and evaluate(condition, env, levels):
                env[arg[0]] = evaluate(arg[1], env, levels)

    def bring(rules):
        for _ in range(3):                   # runlevels bring others: to a fixed point
            switches()
            before = len(levels)
            for condition, action, arg in rules:
                if evaluate(condition, env, levels):
                    levels.extend(x for x in arg if x not in levels)
            if len(levels) == before:
                break
        switches()

    if not new_input:
        bring(data['implied'])               # before the input is read
    bring(data.get('after', []))             # after it is read (GW brings el_el_corr)

    names = {}

    def add(items, on=True):
        for n in items:
            if on:
                names[n] = True
            else:
                names.pop(n, None)

    for condition, action, arg in data['rules']:
        if not evaluate(condition, env, levels):
            continue
        if action in ('activate', 'deactivate'):
            add(arg, action == 'activate')
        elif action == 'cpu':
            env['what'] = arg
            for c, a, x in data['cpu']:
                if evaluate(c, env, levels):
                    add([n.replace('{what}', arg) for n in x], a == 'activate')
        elif action == 'x':
            kind = arg[0] if arg[0].startswith('X') and len(arg[0]) == 2 else env.get(arg[0], '')
            add(stem[:6] + kind for stem in arg[1])
        elif action == 'qp':
            for c, a, x in data['qp']:
                if evaluate(c, env, levels):
                    add([n.replace('{what}', arg) for n in x], a == 'activate')
        elif action == 'set':
            env[arg[0]] = evaluate(arg[1], env, levels)
    # Only names registered as input variables (INIT_load's `it`) are written:
    # activating any other does nothing, as EvalMagn, or RIM_W_diag, read in
    # the code with `parser` but never registered (5.3)
    return [InputName(n, info.get(n)) for n in levels] + \
        [InputName(n, info[n]) for n in names if n not in levels and n in info]


# -- the conditions' small language ---------------------------------------------------------

_ALLOWED = (ast.Expression, ast.BoolOp, ast.And, ast.Or, ast.UnaryOp, ast.Not, ast.Compare,
            ast.Eq, ast.NotEq, ast.Lt, ast.Gt, ast.LtE, ast.GtE, ast.Name, ast.Load,
            ast.Constant, ast.Call)
_FUNCTIONS = {'any_', 'all_', 'has', 'match', 'same', 'runlevel'}


def evaluate(expression, env, runlevels=()):
    """A condition of the extracted rules, with `env` (switches, Fortran
    variables) and the runlevels on. Unknown switches (``l_...``) are off."""
    tree = ast.parse(expression, mode='eval')
    for node in ast.walk(tree):
        if not isinstance(node, _ALLOWED):
            raise ValueError(f'{expression!r}: {type(node).__name__} is not allowed')
        if isinstance(node, ast.Call) and not (isinstance(node.func, ast.Name)
                                               and node.func.id in _FUNCTIONS):
            raise ValueError(f'{expression!r}: only {", ".join(sorted(_FUNCTIONS))} may be called')
    return _eval(tree.body, env, set(runlevels))


def _text(value):
    return '' if value is None else str(value).strip().strip('"').strip("'")


def _eval(node, env, runlevels):
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Name):
        if node.id in ('True', 'False'):
            return node.id == 'True'
        return env.get(node.id, False if node.id.startswith('l_') else None)
    if isinstance(node, ast.BoolOp):
        values = (_eval(v, env, runlevels) for v in node.values)
        return all(values) if isinstance(node.op, ast.And) else any(values)
    if isinstance(node, ast.UnaryOp):
        return not _eval(node.operand, env, runlevels)
    if isinstance(node, ast.Compare):
        left = _eval(node.left, env, runlevels)
        for op, right_node in zip(node.ops, node.comparators):
            right = _eval(right_node, env, runlevels)
            a, b = left, right
            if isinstance(a, str) or isinstance(b, str):
                a, b = _text(a), _text(b)
            else:
                a = 0 if a is None else a
                b = 0 if b is None else b
                try:
                    a, b = float(a), float(b)
                except (TypeError, ValueError):
                    pass
            ok = {ast.Eq: a == b, ast.NotEq: a != b}.get(type(op))
            if ok is None:
                try:
                    ok = {ast.Lt: a < b, ast.Gt: a > b, ast.LtE: a <= b, ast.GtE: a >= b}[type(op)]
                except TypeError:
                    ok = False
            if not ok:
                return False
            left = right
        return True
    if isinstance(node, ast.Call):
        args = [_eval(a, env, runlevels) for a in node.args]
        name = node.func.id
        if name == 'any_':
            return any(args)
        if name == 'all_':
            return all(args)
        if name == 'runlevel':
            return args[0] in runlevels
        text, word = _text(args[0]).lower(), _text(args[1]).lower()
        if name == 'has':
            return word in text
        if name == 'match':
            return word in text
        return text == word                  # same
    raise ValueError(f'{type(node).__name__} is not allowed')
